function municipalSummary(name:string):string|null {
  if(name==="regionalPlanningApplications")return "Published regional application boundaries intersect the subject point. Preserve separate legacy/new statuses and dates; regional commenting and review do not establish municipal approval, current permission or full planning history.";
  if(name==="employmentInventory2025")return "Published 2025 employment-land inventory mapping intersects the subject point. Current zoning, conversion permission, servicing and present-day development status remain unverified.";
  if(name==="wellheadProtection")return "Published wellhead-protection mapping intersects the subject point. This does not establish water safety, contamination, an actual water connection or current activity-specific requirements.";
  if(name==="durhamPlanning")return "Published 2024 regional planning mapping intersects the confirmed municipal point. Current municipal amendments, parcel-wide constraints and drinking-water safety remain unverified; read every nested status.";
  if(name==="secondaryPlans")return "Published secondary-plan areas and source Statutory/Non-Statutory classifications intersect the point; current applicable policies, amendments and appeals are unverified.";
  if(name==="developmentChargeAreas")return "Published development-charge areas and source classifications intersect the point; current fees, payment, exemptions and actual servicing are unverified.";
  if(name==="municipality")return "A published municipal boundary confirms the point's requested municipality; this does not verify title or a surveyed property boundary.";
  if(name.includes("2010"))return "Historical mapping from Mississauga's repealed 2010 plan is available; it does not establish current Official Plan 2051 designations or constraints.";
  return ({heritageDistrict:"Published heritage district mapping intersects the point; verify current district and property-specific alteration requirements.",generalizedLandUse:"A generalized land-use classification is available; detailed zone codes, exceptions and permitted uses are not supplied.",primaryTransitArea:"The point is in a published Primary Transit Area; verify current service and applicable policies.",communityImprovementArea:"A published improvement-project area intersects the point; current funding and eligibility are unverified.",existingLandUse:"Published existing-use classification intersects the point; it does not establish Official Plan policy, approved uses or a legal unit count.",rentalLicences:"Issued rental-licence evidence matched the civic address. Read the published expiry and file vintage; current validity, renewal and revocation status are unverified.",community:"A published municipal community boundary intersects the point; this does not classify household or neighbourhood quality."} as Record<string,string>)[name]??null;
}
